/bin/bash -c "python - <<'PY'
from bioblend.galaxy import GalaxyInstance
import inspect, os
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
gi=GalaxyInstance(os.environ['GALAXY_URL'].strip(), key=key)
print([m for m in dir(gi.tools) if 'upload' in m or 'paste' in m or 'file' in m])
for m in dir(gi.tools):
 if 'upload' in m or 'paste' in m:
  try: print(m, inspect.signature(getattr(gi.tools,m)))
  except Exception as e: print(e)
print('hist methods with upload:', [m for m in dir(gi.histories) if 'upload' in m])
print('version', gi.config.get_version())
PY"

